<script lang="ts">
  import * as Dialog from "$lib/components/ui/dialog";
  import { dialogState } from "./dialog-state.svelte";
  import { Button } from "$lib/components/ui/button";
  import { COMPONENT_INFOS } from "../dynamic_layout_test/all_components.svelte";
  import { BetweenVerticalStart, ChevronsDownUp, Link, SquareArrowRight } from "@lucide/svelte";

  let shouldShowDialog = $derived(dialogState.showAddNodeDialog !== null);

  function handleSelectNodeType (type: string) {
    dialogState.showAddNodeDialog?.onSubmit(type);
    dialogState.showAddNodeDialog = null;
  }

  const NodeGroupToLabel = {
    LAYOUT: "Layout",
    NODE: "Nodes",
    FUN: "Fun"
  };

  const NodeTypesToHide = ["tab", "dashboard"];

  const AllowedNodeTypes = $derived(Object.keys(COMPONENT_INFOS)
    .filter(nodetype => !NodeTypesToHide.includes(nodetype)));
  const GroupedByNodeTypes = $derived(AllowedNodeTypes.reduce((acc, nodeType) => {
    const group = NodeGroupToLabel[COMPONENT_INFOS[nodeType].nodeGroup ?? "NODE"];
    if (!acc[group]) {
      acc[group] = [];
    }
    acc[group].push(nodeType);
    return acc;
  }, {} as Record<string, string[]>));

</script>

<Dialog.Root open={shouldShowDialog} onOpenChange={(opened) => {
  if (!opened) {
    setTimeout(() => {
      dialogState.showAddNodeDialog = null;
    }, 100);
  }
}}>
  <Dialog.Content>
    <Dialog.Header>
      <Dialog.Title>Add New Node</Dialog.Title>
      <Dialog.Description>Select a node type to add.</Dialog.Description>
    </Dialog.Header>

    <Dialog.Overflow styles="padding: 0.25rem">
      <div>
        {#each Object.keys(GroupedByNodeTypes) as group}
          <div>
            <h3 class="text-lg font-semibold">{group}</h3>
            <div class="grid grid-cols-3 gap-2">
              {#each GroupedByNodeTypes[group] as nodeType}
                <Button onclick={() => handleSelectNodeType(nodeType)}>
                  {#if COMPONENT_INFOS[nodeType].iconComponent}
                    <svelte:component this={COMPONENT_INFOS[nodeType].iconComponent}
                                      class="w-6 h-6 mr-2" />
                  {:else}
                    <svelte:component this={SquareArrowRight} class="w-6 h-6 mr-2" />
                  {/if}
                  {nodeType}
                </Button>
              {/each}
            </div>
          </div>
          <br />
        {/each}
      </div>
    </Dialog.Overflow>
  </Dialog.Content>
</Dialog.Root>
