<script lang="ts">
  import * as Dialog from "$lib/components/ui/dialog";
  import { dialogState } from "./dialog-state.svelte";

  import {
    createForm3,

    type FormInternals,
    type FormState,
    type Schema,
    type UiSchema
  } from "@sjsf/form";
  import { createValidator2 } from "@sjsf/ajv8-validator";
  import { translation } from "@sjsf/form/translations/en";
  import { Tab, Tabs } from "svelte-ux";
  import type {
    JsonSchemaParts,
    SchemaPartsFnOfType,
    SchemaPartsOfType
  } from "../components/dashboard-nodes/jsonSchemaTypes";
  import {
    createJsonSchemaDialogPayload,
    createJsonUiSchemaDialogPayload
  } from "../components/dashboard-nodes/jsonSchemaCombinators";
  import Form from "$lib/blocks/svelte-jsonschema-form/multiple-forms/MultipleForms.form.svelte";

  import { Button } from "$lib/components/ui/button";
  import { setThemeContext, theme } from "@sjsf/shadcn-theme";
  import { icons } from "@sjsf/lucide-icons";
  import { mapSchemaPartsToComponents } from "../components/dashboard-nodes/jsonSchemas";
  import { Inspect } from "svelte-inspect-value";

  const lazyLoadComponents = () => import("./formComponents").then(({ ThemeContext }) => ThemeContext);

  const themeContext = {
    components: {}
  };

  // @ts-expect-error ignore missing components
  setThemeContext(themeContext);


  let showDialog = $derived(dialogState.showJsonSchemaDialog?.type === "tabbed");

  let componentSchemas: JsonSchemaParts[] = $state([]);

  let tabs = $derived.by(() => {
    if (!showDialog) {
      return {};
    }

    return Object.groupBy(componentSchemas, (part) => part.dataTab ?? "general");
  });

  let selectedTab = $state("");

  let contexts: {
    [key: string]: {
      formApi: FormState<any, any> & FormInternals,
      submitButton?: HTMLInputElement,
      schema: Schema,
      uiSchema: UiSchema,
      schemaParts: SchemaPartsOfType,
      formElem?: HTMLFormElement;
      idPrefix: string;
      checkValidate?: () => void;
    }
  } = $state({});

  let randomKeyToRetriggerTheFormContext = $state(crypto.randomUUID());

  let errorAmount = $state({} as { [tab: string]: number });

  let loadingTheme = $state(false);
  let loadedTheme = $state(false);

  async function refreshForms () {
    if (!loadedTheme) {
      return;
    }

    for (let [group, schemaParts] of Object.entries(tabs)) {
      if (!schemaParts) {
        continue;
      }

      const schema = createJsonSchemaDialogPayload(schemaParts);
      const uiSchema = createJsonUiSchemaDialogPayload(schemaParts);

      const idPrefix = `${randomKeyToRetriggerTheFormContext}_form_${group}_parts`;

      const validator = createValidator2({
        uiSchema,
        idPrefix
      });

      const form2Ctx = createForm3({
        schema,
        uiSchema,
        translation,
        validator,
        icons,
        ...theme,

        idPrefix
      });

      form2Ctx.value = {};

      dialogState.showJsonSchemaDialog?.dataByParts(schemaParts).then((data) => {
        form2Ctx.value = data;
      });

      contexts[group] = {
        formApi: form2Ctx,
        schema,
        uiSchema,
        schemaParts,
        idPrefix
      };
    }
  }

  $effect(() => {
    refreshForms();
  });

  async function loadComponents () {
    if (loadingTheme) {
      return;
    }

    if (!loadedTheme) {
      loadingTheme = true;
      const ThemContext = await lazyLoadComponents();

      themeContext.components = ThemContext.components;

      loadedTheme = true;
      loadingTheme = false;
    }

  }

  $effect(() => {
    // log context
   // console.info("contexts", $state.snapshot(contexts));
  })

  $effect(() => {
    if (!showDialog) {
      // on each close, we change the randomUUID
      randomKeyToRetriggerTheFormContext = crypto.randomUUID();

      return;
    }

    loadComponents();


    if (dialogState.showJsonSchemaDialog?.jsonSchemaParts && componentSchemas.length === 0) {
      mapSchemaPartsToComponents(dialogState.showJsonSchemaDialog.jsonSchemaParts).then((result) => {
        componentSchemas = result;
      });
    }


    selectedTab = Object.keys(tabs)[0];

  });

  function triggerSave () {
    const resultPair: { schemaParts: SchemaPartsOfType, value: any }[] = [];

    let hasErrors = false;

    for (let [group, info] of Object.entries(contexts)) {
      info.formApi!.errors = info.formApi!.validate();

      if (info.formApi!.errors.size > 0) {
        errorAmount[group] = info.formApi!.errors.size;
        // console.info("errors", info.formApi!.errors);
        hasErrors = true;
      }

      resultPair.push({
        schemaParts: info.schemaParts,
        value: info.formApi.value
      });
    }

    if (!hasErrors) {
      dialogState.showJsonSchemaDialog?.onSubmit(resultPair);
      dialogState.showJsonSchemaDialog = null;
      handleOpenChange(false);
    }
  }

  function handleOpenChange (opened: boolean) {
    if (!opened) {
      setTimeout(() => {
        dialogState.showJsonSchemaDialog = null;

        Object.keys(contexts).forEach((key) => {
          // console.info("deleting context", key);
          const prevContext = contexts[key];

          delete contexts[key];
          delete errorAmount[key];
        });


        contexts = {};

        // without that, the previous form entries/state will be still there,
        // keeping the current needed form to not be shown
        componentSchemas = [];
      });
    }
  }
</script>


<Dialog.Root open={showDialog} onOpenChange={handleOpenChange}>
  <Dialog.Content class="overflow-hidden md:max-w-[700px] lg:max-w-[800px]">
    <Dialog.Header>
      <Dialog.Title>{dialogState.showJsonSchemaDialog?.title}</Dialog.Title>
      {#if dialogState.showJsonSchemaDialog?.description}
        <Dialog.Description>{dialogState.showJsonSchemaDialog?.description}</Dialog.Description>
      {/if}
    </Dialog.Header>
    <Tabs
      placement="left"
      classes={{
      content: "border px-4 py-2  rounded-r",
    }}
    >
      {#each Object.keys(tabs) as option (option)}
        <Tab classes={{root:"rounded-l"}}
             on:click={() => (selectedTab = option)}
             selected={selectedTab === option}
        >
          {option}
          {#if errorAmount[option] > 0}
            <span class="text-red-500">({errorAmount[option]})</span>
          {/if}
        </Tab>
      {/each}

      <svelte:fragment slot="content">
        <div class="overflow-auto " style="min-height: 400px; max-height: 400px;">
          {#if showDialog && contexts[selectedTab]}
            {@const { idPrefix } = contexts[selectedTab]}

            {#key idPrefix}
              <Form bind:form={contexts[selectedTab].formApi}
                    class="flex flex-col gap-4 mx-1" />
            {/key}
          {/if}
        </div>
      </svelte:fragment>
    </Tabs>

    <div class="flex" class:justify-between={!!dialogState.showJsonSchemaDialog?.onDelete}
         class:justify-end={!dialogState.showJsonSchemaDialog?.onDelete}>
      {#if dialogState.showJsonSchemaDialog?.onDelete}
        <Button variant="destructive" onclick={() => {
          dialogState.showJsonSchemaDialog?.onDelete();
          dialogState.showJsonSchemaDialog = null;
        }}>
          Delete Node
        </Button>
      {/if}

      <Button variant="default" onclick={triggerSave}>
        Save
      </Button>
    </div>
  </Dialog.Content>
</Dialog.Root>
