import { evolu } from './evolu/evolu_instance';
import type { CssClassEntry } from './cssClasses';
import { id } from '@evolu/common';

// TODO

export const CssClassRepository = {
  async addClass(cssClass: Omit<CssClassEntry, 'id'>): Promise<void> {
    await evolu.insert('globalStyles', {
      id: id('GlobalStyle').create(),
      style: cssClass
    });
  },

  async updateClass(cssClass: CssClassEntry): Promise<void> {
    await evolu.update('globalStyles', {
      id: cssClass.id,
      style: cssClass
    });
  },

  async deleteClass(cssClassId: string): Promise<void> {
    await evolu.update('globalStyles', {
      id: cssClassId,
      isDeleted: true
    });
  },

  async getAllClasses(): Promise<CssClassEntry[]> {
    const query = evolu.createQuery((db) =>
      db.selectFrom('globalStyles').selectAll().where('isDeleted', 'is', null)
    );
    const rows = await evolu.loadQuery(query);
    return rows.map((row) => row.style as CssClassEntry);
  },

  async getClass(classId: string): Promise<CssClassEntry> {
    const query = evolu.createQuery((db) =>
      db.selectFrom('globalStyles').selectAll().where('id', '==', classId).where('isDeleted', 'is', null)
    );
    const rows = await evolu.loadQuery(query);
    return rows[0].style as CssClassEntry;
  }
};
