<script lang="ts" generics="T, E">
  import type { HTMLFormAttributes } from "svelte/elements";
  import {
    Content,
    setFromContext,
    type FormState,
    type FormInternals
  } from "@sjsf/form";

  interface Props extends HTMLFormAttributes {
    form: FormState<T, E> & FormInternals;
    formElement?: HTMLFormElement;
  }

  let { form = $bindable(), ...rest }: Props = $props();

  setFromContext(form.context);
</script>

<form use:form.enhance novalidate {...rest}>
  <Content form={form} />
</form>


{#if form.errors.size > 0}
  <div style="padding-top: 1rem;">
    <span style="font-size: larger; font-weight: bold;">Errors</span>
    <ui style="color: red;">
      {#each form.errors as [field, fieldErrors] (field)}
        {#each fieldErrors as err}
          <li>"{err.propertyTitle}" {err.message}</li>
        {/each}
      {/each}
    </ui>
  </div>
{/if}
