import { computePseudoId, toIdSchema2, pathToId, } from "../id-schema.js";
export function makeIdSchema(ctx, schema, id, formData) {
    return toIdSchema2(ctx.validator, ctx.merger, schema, ctx.idPrefix, ctx.idSeparator, [], id, ctx.schema, formData);
}
export function makePseudoId(ctx, instanceId, element) {
    return computePseudoId(ctx.idPseudoSeparator, instanceId, element);
}
export function makeIdFromPath(ctx, path) {
    return pathToId(ctx.idPrefix, ctx.idSeparator, path);
}
export function makeArrayItemId(ctx, parentId, index) {
    return `${parentId}${ctx.idSeparator}${index}`;
}
export function makeObjectPropertyId(ctx, parentId, property) {
    return `${parentId}${ctx.idSeparator}${property}`;
}
