<script lang="ts">
  import {
    type Schema,
    FormContent,
    type UiSchema,
    useForm2,
    SubmitButton,
    SimpleForm,
    ON_INPUT,
    ON_CHANGE,
    AFTER_SUBMITTED, ON_BLUR, ON_OBJECT_CHANGE, ON_ARRAY_CHANGE,
    AFTER_CHANGED
  } from "@sjsf/form";
  import { createValidator2 } from "@sjsf/ajv8-validator";
  import { translation } from "@sjsf/form/translations/en";
  import { icons } from "@sjsf/lucide-icons";
  import type { FormAPI } from "@sjsf/form";


  import { setThemeContext, theme } from "@sjsf/shadcn-theme";
  import { components } from "@sjsf/shadcn-theme/new-york";

  // import { theme} from '@sjsf/form/basic-theme';

  setThemeContext({ components });

  interface Props {
    schema: Schema;
    uiSchema: UiSchema;
    data: any;
    setFormApi: (form: FormAPI<any, any>) => void;
    idPrefix: string;
    onSubmit: (data: any) => void;
    checkValidate?: () => void;
  }

  let {
    schema,
    uiSchema,
    data = $bindable(),
    onSubmit,
    idPrefix,
    setFormApi,
    checkValidate = $bindable()
  }: Props = $props();

  const validator = createValidator2({
      idPrefix,
      uiSchema
    })

  const form = useForm2({
    ...theme,
    schema,
    uiSchema,
    validator ,

    translation,
    icons,
    onSubmit,
    // none of them helped ^^
    fieldsValidationMode: ON_INPUT | ON_CHANGE | ON_BLUR | ON_OBJECT_CHANGE | ON_ARRAY_CHANGE,
focusFirstError: true,

    idPrefix
  });

  form.value = data;

  setFormApi(form);

  checkValidate = () => {
    form.errors = form.validate();
  };
</script>
<form use:form.enhance novalidate class="flex flex-col gap-4">
  <!-- svelte-ignore ownership_invalid_binding -->
  <FormContent bind:value={form.formValue} />
</form>

Schema: <br/>{JSON.stringify(schema)} <br/> <br/>
UISchema: <br/>{JSON.stringify(uiSchema)} <br/>

{#if form.errors.size > 0}
  <div style="padding-top: 1rem;">
    <span style="font-size: larger; font-weight: bold;">Errors</span>
    <ui style="color: red;">
      {#each form.errors as [field, fieldErrors] (field)}
        {#each fieldErrors as err}
          <li>"{err.propertyTitle}" {err.message}</li>
        {/each}
      {/each}
    </ui>
  </div>
{/if}
