<script lang="ts">
  import * as Dialog from "$lib/components/ui/dialog";
  import { dialogState } from "./dialog-state.svelte";
  import { Button } from "$lib/components/ui/button";
  import { onMount } from "svelte";
  import type { CssClassEntry } from "$lib/state/cssClasses";
  import { CssClassRepository } from "$lib/database/cssClassRepository.svelte";

  let cssClasses = $state<CssClassEntry[]>([]);
  let selectedCssClass = $state<CssClassEntry | null>(null);

  onMount(async () => {
    cssClasses = await CssClassRepository.getAllClasses();
  });

  function handleAdd () {
    selectedCssClass = {
      id: "",
      className: "",
      styles: ""
    };
  }

  function handleEdit (cssClass: CssClassEntry) {
    selectedCssClass = { ...cssClass };
  }

  function handleDelete (cssClassId: string) {
    CssClassRepository.deleteClass(cssClassId);
    cssClasses = cssClasses.filter(cls => cls.id !== cssClassId);
  }

  async function handleSubmit () {
    if (!selectedCssClass) {
      return;
    }

    if (selectedCssClass.id) {
      CssClassRepository.updateClass(selectedCssClass);
    } else {
      CssClassRepository.addClass(selectedCssClass);
    }

    cssClasses = await CssClassRepository.getAllClasses();
    selectedCssClass = null;
  }
</script>

<Dialog.Root open={dialogState.showCssClassDialog !== null} onOpenChange={(opened) => {
  if (!opened) {
    setTimeout(() => {
      dialogState.showCssClassDialog = null;
    }, 100);
  }
}}>
  <Dialog.Content>
    <Dialog.Header>
      <Dialog.Title>Manage CSS Classes</Dialog.Title>
      <Dialog.Description>List, add, update, and delete CSS classes.</Dialog.Description>
    </Dialog.Header>

    <Dialog.Overflow styles="padding: 0.25rem">
      <Button onclick={handleAdd}>Add CSS Class</Button>
      <ul>
        {#each cssClasses as cssClass}
          <li>
            {cssClass.className}
            <Button onclick={() => handleEdit(cssClass)}>Edit</Button>
            <Button onclick={() => handleDelete(cssClass.id)}>Delete</Button>
          </li>
        {/each}
      </ul>

      {#if selectedCssClass}
        <form on:submit|preventDefault={handleSubmit}>
          <label>
            Class Name:
            <input type="text" bind:value={selectedCssClass.className} required />
          </label> <br/>
          <label>
            Styles:
            <textarea bind:value={selectedCssClass.styles} required></textarea>
          </label>
          <br/>
          <Button type="submit">Save</Button>
        </form>
      {/if}
    </Dialog.Overflow>
  </Dialog.Content>
</Dialog.Root>
