export function getArrayItemName(config, index) {
    return `${config.name}__${index}`;
}
function titleWithIndex(title, index) {
    return `${title}-${index + 1}`;
}
export function getNormalArrayItemTitle({ uiOptions, schema, title }, index) {
    return titleWithIndex(uiOptions?.title ?? schema.title ?? title, index);
}
export function getFixedArrayItemTitle({ uiSchema: { items: uiItems }, schema: { items }, title }, index) {
    if (Array.isArray(uiItems)) {
        const title = uiItems[index]?.["ui:options"]?.title;
        if (title) {
            return title;
        }
        uiItems = undefined;
    }
    if (Array.isArray(items)) {
        const item = items[index];
        if (typeof item === "object" && item.title) {
            return item.title;
        }
        items = undefined;
    }
    return titleWithIndex(uiItems?.["ui:options"]?.title ||
        (typeof items === "object" && items?.title) ||
        title, index);
}
