<script lang="ts">
  import * as Dialog from "$lib/components/ui/dialog";
  import { dialogState } from "./dialog-state.svelte";
  import { components } from "@sjsf/shadcn-theme/new-york";
  import { setThemeContext } from "@sjsf/shadcn-theme";
  import { Button } from "$lib/components/ui/button";
  import { NodeRepository } from "$lib/database/nodeRepository.svelte";
  import { convertDbNodeToDynamicLayoutNode } from "$lib/database/layoutDbNodeConverter";
  import {
    type DynamicLayoutNode
  } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";
  import { getLabel } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types.js";

  setThemeContext({ components });

  let selectedNodeId = $state<string | null>(null);
  let availableNodes = $state<DynamicLayoutNode[]>([]);

  let shouldShowDialog = $derived(dialogState.showChangeParentDialog !== null);

  $effect(() => {
    // TODO after MVP
    if (!shouldShowDialog){
      availableNodes = [];
      return;
    }

    if (shouldShowDialog && availableNodes.length === 0) {
      NodeRepository.getAllNodesAsync().then((nodes) => {
        availableNodes =  nodes.map(convertDbNodeToDynamicLayoutNode);
      });
    }
  });

  function handleSubmit() {
    if (selectedNodeId) {
      dialogState.showChangeParentDialog?.onSubmit(selectedNodeId);
      dialogState.showChangeParentDialog = null;
    }
  }
</script>

<Dialog.Root open={dialogState.showChangeParentDialog !== null} onOpenChange={(opened) => {
  if (!opened) {
    setTimeout(() => {
      dialogState.showChangeParentDialog = null;
    }, 100);
  }
}}>
  <Dialog.Content>
    <Dialog.Header>
      <Dialog.Title>Change Parent Node</Dialog.Title>
      <Dialog.Description>Select a new parent for the node.</Dialog.Description>
    </Dialog.Header>

    <Dialog.Overflow styles="padding: 0.25rem">
      <select bind:value={selectedNodeId}>
        <option value="" disabled>Select a node</option>
        {#each availableNodes as node}
          <option value={node.id}>{getLabel(node) ?? node.id} ({node.type})</option>
        {/each}
      </select>
    </Dialog.Overflow>

    <div class="flex justify-end">
      <Button variant="default" onclick={handleSubmit}>Submit</Button>
    </div>
  </Dialog.Content>
</Dialog.Root>
