import { createMessage } from '../error-message.svelte';
function getTemplateInternal(ctx, type, config) {
    const template = config.uiSchema["ui:templates"]?.[type];
    switch (typeof template) {
        case "undefined":
            return ctx.templates(type, config);
        case "string":
            return ctx.templates(template, config);
        default:
            return template;
    }
}
export function getTemplate(ctx, type, config) {
    return (getTemplateInternal(ctx, type, config) ??
        createMessage(`Template "${config.uiSchema["ui:templates"]?.[type] ?? type}" not found`));
}
