<script lang="ts">
  import "../app.postcss";
  import Header from "./Header.svelte";
  import "github-markdown-css/github-markdown.css";
  import "./styles.css";
  import { dev } from "$app/environment";
  import { page } from "$app/state";

  import { pwaInfo } from "virtual:pwa-info";
  import { onMount } from "svelte";
  import { Separator } from "$lib/components/ui/separator";

  import * as Breadcrumb from "$lib/components/ui/breadcrumb";
  import * as Sidebar from "$lib/components/ui/sidebar";
  import AppSidebar from "$lib/layout/app-sidebar.svelte";
  import ChevronsUpDown from "@lucide/svelte/icons/chevrons-up-down";
  import { initializeContexts } from "$lib/state/app-state.svelte";
  import ChangeParentDialog from "$lib/dialogs/ChangeParentDialog.svelte";
  import GlobalSettingDialog from "$lib/dialogs/GlobalSettingDialog.svelte";
  import AddNodeDialog from "$lib/dialogs/AddNodeDialog.svelte";
  import CssClassDialog from "$lib/dialogs/CssClassDialog.svelte";
  import TabbedJsonSchemaFormDialog from "$lib/dialogs/TabbedJsonSchemaFormDialog.svelte";
  import DataSourceDialog from "$lib/dialogs/DataSourceDialog.svelte";
  import GenericJsonSchemaFormDialog from "$lib/dialogs/GenericJsonSchemaFormDialog.svelte";
  import SveltePortal from "$lib/blocks/svelte-utils/portal/SveltePortal.svelte";

  interface Props {
    children?: import("svelte").Snippet;
  }

  let { children }: Props = $props();

  let showRenderScan = page.url.searchParams.get("showRenderScan") === "true";

  let renderScanComponentLazy = $derived(showRenderScan ? import("svelte-render-scan").then(value => value.RenderScan) : null);

  onMount(async () => {
    if (pwaInfo) {
      // ts-ignore
      const { registerSW } = await import(
        // ts-ignore
        "virtual:pwa-register"
        );

      console.log("Registering SW");
      registerSW({
        immediate: true,
        scope: "/codename_dashboard/",
        onRegistered (r) {
          // uncomment following code if you want check for updates
          // r && setInterval(() => {
          //    console.log('Checking for sw update')
          //    r.update()
          // }, 20000 /* 20s for testing purposes *)
          console.log(`SW Registered: ${r}`);
        },
        onRegisterError (error) {
          console.log("SW registration error", error);
        }
      });
    }
  });

  $effect(() => console.info("PWA Info", pwaInfo));
  let webManifestLink = pwaInfo ? pwaInfo.webManifest.linkTag : "";

  initializeContexts();

</script>


<svelte:head>
  {@html webManifestLink}
</svelte:head>


<Sidebar.Provider style="--sidebar-width-icon: 3.5rem">

  <AppSidebar />

  <Sidebar.Inset>
    <header
      class="flex h-16 shrink-0 items-center gap-2 transition-[width,height] ease-linear group-has-[[data-collapsible=icon]]/sidebar-wrapper:h-12"
    >
      <div class="flex items-center gap-2 px-4">
        <Sidebar.Trigger class="-ml-1" />
        <Separator orientation="vertical" class="mr-2 h-4" />
        <Breadcrumb.Root>
          <Breadcrumb.List>
            <Breadcrumb.Item class="hidden md:block">
    <SveltePortal name="header-title"></SveltePortal>
            </Breadcrumb.Item>
          </Breadcrumb.List>
        </Breadcrumb.Root>
      </div>
    </header>

    <div class="app">
      <Header />

      <main>
        {@render children?.()}
      </main>
    </div>

  </Sidebar.Inset>
</Sidebar.Provider>


{#if showRenderScan}
  {#await renderScanComponentLazy then RenderScan}
    <RenderScan />
  {/await}
{/if}

<AddNodeDialog />
<GenericJsonSchemaFormDialog />
<TabbedJsonSchemaFormDialog />
<ChangeParentDialog />
<GlobalSettingDialog />
<DataSourceDialog />
<CssClassDialog />

<style>
  .app {
     height: 100%;

     main {
        height: 100%;
        overflow: auto;

       :global( > .flex) {
          height: 100%;
       }
     }
  }
</style>
