<script lang="ts">
  import * as Dialog from "$lib/components/ui/dialog";
  import { dialogState } from "./dialog-state.svelte";

  import { setThemeContext } from "@sjsf/shadcn-theme";
  import FormBySchema from "./FormBySchema.svelte";
  import {
    createJsonSchemaDialogPayload,
    createJsonUiSchemaDialogPayload
  } from "../components/dashboard-nodes/jsonSchemaCombinators";
  import type { JsonSchemaParts } from "../components/dashboard-nodes/jsonSchemaTypes";
  import { mapSchemaPartsToComponents } from "../components/dashboard-nodes/jsonSchemas";

  /**
   function customValidate (
   value: SchemaValue | undefined
   ): ValidationError<ErrorObject>[] {
   if (typeof value === "object" && isTemplate(value)) {
   if (value.label.includes("{{")) {
   return valuePlaceholderCheck(value.label, value.payloadFields.map((field) => "payload." + field.label));
   }
   }
   return [];
   }

   class CustomAjvValidator extends Validator implements FormValidator2 {
   override validateFormData (
   schema: Schema,
   formData: SchemaValue | undefined
   ): ValidationError<ErrorObject>[] {
   return super.validateFormData(schema, formData).concat(customValidate(formData));
   }
   }

   type ValidatorOptions3 = Omit<ValidatorOptions, "ajv"> & {
   ajvOptions?: Options;
   ajv?: Ajv;
   };

   export function createValidator3 ({
   ajvOptions = DEFAULT_AJV_CONFIG,
   ajv = addFormComponents(new Ajv(ajvOptions)),
   ...rest
   }: ValidatorOptions3 = {}) {
   return new CustomAjvValidator({
   ajv,
   ...rest
   });
   }
   */


  const lazyLoadComponents = () => import("./formComponents").then(({ ThemeContext }) => ThemeContext);

  const themeContext = {
    components: {}
  };

  // @ts-expect-error ignore missing components
  setThemeContext(themeContext);

    let loadingTheme = $state(false);
  let loadedTheme = $state(false);

  async function loadComponents () {
    if (loadingTheme) {
      return;
    }

    if (!loadedTheme) {
      loadingTheme = true;
      const ThemContext = await lazyLoadComponents();

      themeContext.components = ThemContext.components;

      loadedTheme = true;
      loadingTheme = false;
    }

  }

  let showDialog = $derived(dialogState.showJsonSchemaDialog?.type === "simple");

  let componentSchemas: JsonSchemaParts[] = $state([]);

  $effect(() => {
    loadComponents();

        if (!loadedTheme) {
      return;
    }

    if (dialogState.showJsonSchemaDialog?.jsonSchemaParts) {
      mapSchemaPartsToComponents(dialogState.showJsonSchemaDialog.jsonSchemaParts).then((result) => {
        componentSchemas = result;
      });
    }
  });
</script>

<Dialog.Root open={showDialog} onOpenChange={(opened) => {
  if(!opened) {
    setTimeout(() => {
      dialogState.showJsonSchemaDialog = null;
    }, 100);
  }
}}>
  <Dialog.Content>
    <Dialog.Header>
      <Dialog.Title>{dialogState.showJsonSchemaDialog?.title}</Dialog.Title>
      {#if dialogState.showJsonSchemaDialog?.description}
        <Dialog.Description>{dialogState.showJsonSchemaDialog?.description}</Dialog.Description>
      {/if}
    </Dialog.Header>

    <Dialog.Overflow styles="padding: 0.25rem">
      {#if showDialog}
        {@const schema = createJsonSchemaDialogPayload(componentSchemas)}
        {@const uiSchema = createJsonUiSchemaDialogPayload(componentSchemas)}
        {@const dataPromise = dialogState.showJsonSchemaDialog?.dataByParts(componentSchemas)}

        {#await dataPromise}
          <div>Loading Form Data ...</div>
        {:then data}
          <FormBySchema
            schema={schema}
            uiSchema={uiSchema}
            data={data}
            onSubmit={(data) => {
              dialogState.showJsonSchemaDialog?.onSubmit([
                {
                  schemaParts: componentSchemas,
                  value: data
                }
              ]);
              dialogState.showJsonSchemaDialog = null;
            }}
          />
        {/await}
      {/if}
    </Dialog.Overflow>
  </Dialog.Content>
</Dialog.Root>
